from fractions import Fraction
from typing import List, Sequence

PS = List[Fraction]  # a truncated power series: the 1-unit part u = q*f of a normalized f


def ps_mul(a: Sequence[Fraction], b: Sequence[Fraction], prec: int) -> PS:
    """Truncated Cauchy product, O(prec^2) coefficient operations."""
    out = [Fraction(0)] * prec
    for i in range(min(prec, len(a))):
        if a[i] == 0:
            continue
        for j in range(min(prec - i, len(b))):
            if b[j] != 0:
                out[i + j] += a[i] * b[j]
    return out


def corrected_product(units: Sequence[PS], prec: int) -> PS:
    """1-unit part of the corrected product f_1 * ... * f_m = q^{m-1} f_1 ... f_m."""
    acc: PS = [Fraction(0)] * prec
    acc[0] = Fraction(1)
    for u in units:
        assert u[0] == 1, "each factor must be normalized"
        acc = ps_mul(acc, u, prec)
    return acc


def correcting_exponent(m: int) -> int:
    """The unique k with q^k * (product of m normalized series) normalized."""
    return m - 1


def plain_product_pole_order(m: int) -> int:
    """Pole order at q = 0 of the uncorrected product of m normalized series."""
    return m


def required_input_precision(target: int, m: int) -> int:
    """Laurent degree needed in each factor to know the product through q^target."""
    return target + m - 1

