def binomial_series(r: Fraction, prec: int) -> PS:
    """Coefficients of (1 + X)^r = sum_k binom(r, k) X^k, exact over Q."""
    out = [Fraction(0)] * prec
    out[0] = Fraction(1)
    for k in range(1, prec):
        out[k] = out[k - 1] * (r - (k - 1)) / k
    return out


def substitute_no_const(outer: Sequence[Fraction], inner: Sequence[Fraction], prec: int) -> PS:
    """Horner evaluation of `outer` at `inner`; requires inner[0] == 0."""
    assert inner[0] == 0, "substitution requires vanishing constant term"
    acc: PS = [Fraction(0)] * prec
    for c in reversed(list(outer)):
        acc = ps_mul(acc, inner, prec)
        acc[0] += c
    return acc


def corrected_root(u: Sequence[Fraction], n: int, prec: int) -> PS:
    """The unique 1-unit v with v^n = u, i.e. the corrected n-th root of f = q^{-1} u."""
    assert u[0] == 1 and n >= 1
    h = list(u)
    h[0] = Fraction(0)                       # h = u - 1
    return substitute_no_const(binomial_series(Fraction(1, n), prec), h, prec)


def rational_corrected_power(u: Sequence[Fraction], r: Fraction, prec: int) -> PS:
    """The unique 1-unit v with v^{r.denominator} = u^{r.numerator}."""
    assert u[0] == 1
    h = list(u)
    h[0] = Fraction(0)
    return substitute_no_const(binomial_series(r, prec), h, prec)

from fractions import Fraction
from typing import List, Sequence

PS = List[Fraction]


def ps_mul(a: Sequence[Fraction], b: Sequence[Fraction], prec: int) -> PS:
    out = [Fraction(0)] * prec
    for i in range(min(prec, len(a))):
        if a[i] == 0:
            continue
        for j in range(min(prec - i, len(b))):
            if b[j] != 0:
                out[i + j] += a[i] * b[j]
    return out


def ps_pow(a: Sequence[Fraction], n: int, prec: int) -> PS:
    """Binary exponentiation: O(log n) truncated multiplications."""
    result: PS = [Fraction(0)] * prec
    result[0] = Fraction(1)
    base = list(a)
    e = n
    while e > 0:
        if e & 1:
            result = ps_mul(result, base, prec)
        base = ps_mul(base, base, prec)
        e >>= 1
    return result


def ps_inv_one_unit(a: Sequence[Fraction], prec: int) -> PS:
    v: PS = [Fraction(0)] * prec
    v[0] = Fraction(1)
    for k in range(1, prec):
        v[k] = -sum((a[j] * v[k - j] for j in range(1, k + 1)), Fraction(0))
    return v


def binomial_series(r: Fraction, prec: int) -> PS:
    out: PS = [Fraction(0)] * prec
    out[0] = Fraction(1)
    for k in range(1, prec):
        out[k] = out[k - 1] * (r - (k - 1)) / k
    return out


def substitute_no_const(outer: Sequence[Fraction], inner: Sequence[Fraction], prec: int) -> PS:
    acc: PS = [Fraction(0)] * prec
    for c in reversed(list(outer)):
        acc = ps_mul(acc, inner, prec)
        acc[0] += c
    return acc


def rational_power_by_root_and_power(u: Sequence[Fraction], r: Fraction, prec: int) -> PS:
    """f^r computed as (d-th root)^p for r = p/d in lowest terms, p possibly negative."""
    d, p = r.denominator, r.numerator
    h = list(u)
    h[0] = Fraction(0)
    root = substitute_no_const(binomial_series(Fraction(1, d), prec), h, prec)
    if p >= 0:
        return ps_pow(root, p, prec)
    return ps_pow(ps_inv_one_unit(root, prec), -p, prec)


def rational_power_by_binomial(u: Sequence[Fraction], r: Fraction, prec: int) -> PS:
    """f^r computed directly as the substitution of u - 1 into (1 + X)^r."""
    h = list(u)
    h[0] = Fraction(0)
    return substitute_no_const(binomial_series(r, prec), h, prec)


def agree(a: Sequence[Fraction], b: Sequence[Fraction]) -> bool:
    """Uniqueness of rational corrected powers: the two routes must coincide."""
    return list(a) == list(b)
